// bff/src/routes/handoff.ts
function handoffRoutes(deps) {
  const app2 = new Hono3();
  const { store, staffSession, staffWriter, closeEnquiryQuotation: closeEnquiryQuotation2 } = deps;
  app2.get("/handoff", async (c) => {
    const auth = staffSession(c);
    if (!auth.ok) return c.redirect("/login?next=%2Fhandoff");
    return c.html(renderHandoffPageHtml(await store.pausedThreads(), auth.role ?? "staff"));
  });
  app2.post("/handoff/:phone/resume", async (c) => {
    const auth = staffSession(c);
    if (!auth.ok) return c.json({ error: "unauthorized" }, 401);
    if (!staffWriter(c)) return c.json({ error: "forbidden", detail: "only staff may hand a thread back" }, 403);
    await store.resume(c.req.param("phone"));
    return c.redirect("/handoff");
  });
  app2.post("/handoff/:phone/reset", async (c) => {
    const auth = staffSession(c);
    if (!auth.ok) return c.json({ error: "unauthorized" }, 401);
    if (!staffWriter(c)) return c.json({ error: "forbidden", detail: "only staff may clear a thread" }, 403);
    await closeEnquiryQuotation2(c.req.param("phone"));
    await store.clear(c.req.param("phone"));
    return c.redirect("/handoff");
  });
  return app2;
}

// bff/src/routes/whatsapp.ts
function whatsAppRoutes(deps) {
  const app2 = new Hono3();
  const { store, providerFor, estimator, handoffAuthorized } = deps;
  app2.get("/v1/channels/whatsapp/webhook", (c) => {
    const config2 = whatsAppConfig();
    if (!config2.verifyToken) {
      return c.json({ error: "server_misconfigured", detail: "WHATSAPP_VERIFY_TOKEN is not set" }, 500);
    }
    const challenge = c.req.query("hub.challenge");
    if (c.req.query("hub.mode") === "subscribe" && c.req.query("hub.verify_token") === config2.verifyToken && challenge) {
      return c.text(challenge);
    }
    return c.json({ error: "invalid_verify_token" }, 403);
  });
  app2.post("/v1/channels/whatsapp/webhook", async (c) => {
    const config2 = whatsAppConfig();
    if (!config2.appSecret) {
      return c.json({ error: "server_misconfigured", detail: "WHATSAPP_APP_SECRET is not set" }, 500);
    }
    const raw2 = await c.req.text();
    if (!verifySignature(raw2, c.req.header("x-hub-signature-256"), config2.appSecret)) {
      return c.json({ error: "invalid_signature" }, 401);
    }
    let payload;
    try {
      payload = JSON.parse(raw2);
    } catch {
      return c.json({ error: "invalid_json" }, 400);
    }
    const inbound = parseInboundTexts(payload);
    if (inbound.length === 0) {
      return c.json({ received: 0, replied: 0, duplicates: 0, failed: 0, handoffs: 0 });
    }
    let provider;
    let sendText;
    try {
      provider = await providerFor({});
      sendText = deps.sendWhatsApp ?? createWhatsAppSender(config2);
    } catch (err) {
      return c.json({ error: "server_misconfigured", detail: err instanceof Error ? err.message : String(err) }, 500);
    }
    let replied = 0;
    let duplicates = 0;
    let failed = 0;
    let handoffs = 0;
    const claimedInbound = [];
    for (const message of inbound) {
      const claim2 = await store.claimMessage(message.id);
      if (!claim2.claimed) {
        duplicates++;
        continue;
      }
      claimedInbound.push({ message, fenceToken: claim2.fenceToken });
    }
    const byPhone = /* @__PURE__ */ new Map();
    for (const item of claimedInbound) {
      const list2 = byPhone.get(item.message.from) ?? [];
      list2.push(item);
      byPhone.set(item.message.from, list2);
    }
    for (const [phone, batch] of byPhone) {
      const result = await processPhoneTurnBatch(phone, batch, {
        store,
        provider,
        sendWhatsApp: sendText,
        estimator,
        config: config2
      });
      replied += result.replied;
      failed += result.failed;
      handoffs += result.handoffs;
    }
    return c.json({ received: inbound.length, replied, duplicates, failed, handoffs });
  });
  app2.get("/v1/channels/whatsapp/threads", async (c) => {
    if (!handoffAuthorized(c.req.header("x-verify-token"))) {
      return c.json({ error: "unauthorized" }, 401);
    }
    return c.json({ paused: await store.pausedThreads() });
  });
  app2.post("/v1/channels/whatsapp/threads/:phone/resume", async (c) => {
    if (!handoffAuthorized(c.req.header("x-verify-token"))) {
      return c.json({ error: "unauthorized" }, 401);
    }
    const phone = c.req.param("phone");
    await store.resume(phone);
    return c.json({ ok: true, phone });
  });
  app2.post("/v1/channels/whatsapp/threads/:phone/reset", async (c) => {
    if (!handoffAuthorized(c.req.header("x-verify-token"))) {
      return c.json({ error: "unauthorized" }, 401);
    }
    const phone = c.req.param("phone");
    await closeEnquiryQuotation(phone);
    await store.clear(phone);
    return c.json({ ok: true, phone, reset: true });
  });
  app2.get("/v1/channels/whatsapp/status", async (c) => {
    if (!handoffAuthorized(c.req.header("x-verify-token"))) {
      return c.json({ error: "unauthorized" }, 401);
    }
    const config2 = whatsAppConfig();
    return c.json({
      configured: {
        verifyToken: Boolean(config2.verifyToken),
        appSecret: Boolean(config2.appSecret),
        accessToken: Boolean(config2.accessToken),
        phoneNumberId: Boolean(config2.phoneNumberId)
      },
      sender: await checkSenderCredentials(config2)
    });
  });
  return app2;
}

