// bff/src/routes/quotes/index.ts
function quotesRoutes(deps) {
  const app2 = new Hono3();
  app2.route("/", studioRoutes(deps));
  app2.route("/", guestPageRoutes(deps));
  app2.route("/", listRoutes(deps));
  app2.route("/", recordRoutes(deps));
  app2.route("/", pricingRoutes(deps));
  app2.route("/", publishRoutes(deps));
  app2.route("/", bookingRoutes(deps));
  return app2;
}

// bff/src/app.ts
function createApp(options = {}) {
  const app2 = new Hono3();
  app2.onError((err, c) => {
    console.error(`[casa-bff] unhandled error on ${c.req.method} ${c.req.url}:`, err);
    return c.json(
      {
        ok: false,
        reason: "internal_error",
        error: err instanceof Error ? err.message : String(err)
      },
      500
    );
  });
  const d = createDeps(options.env ?? loadEnv(), options);
  const { staffSession, staffWriter, adminGuard, handoffAuthorized } = d.guards;
  app2.use(
    "*",
    secureHeaders({
      xFrameOptions: "DENY",
      xContentTypeOptions: "nosniff",
      referrerPolicy: "same-origin",
      contentSecurityPolicy: void 0
    })
  );
  app2.route("/", authRoutes({ loginLimiter: d.loginLimiter, setSession: (c, role) => setSession(c, role) }));
  app2.route("/", adminRoutes({ settings: d.settings, guard: adminGuard }));
  app2.route("/", healthRoutes());
  app2.route("/", pageRoutes({ staffSession }));
  app2.route("/", docsRoutes({ staffSession }));
  app2.route("/", extractorRoutes({ providerFor: d.providerFor, staffWriter, staffSession, saveQuotationDraft }));
  app2.route("/", handoffRoutes({ store: d.store, staffSession, staffWriter, closeEnquiryQuotation }));
  app2.route(
    "/",
    whatsAppRoutes({
      store: d.store,
      providerFor: d.providerFor,
      sendWhatsApp: d.sendWhatsApp,
      estimator: d.estimator,
      handoffAuthorized
    })
  );
  app2.route(
    "/",
    quotesRoutes({
      estimator: d.estimator,
      providerHolder: d.providerHolder,
      optionsProvider: d.injectedProvider,
      staffSession,
      staffWriter,
      sendWhatsApp: d.sendWhatsApp
    })
  );
  return app2;
}

